PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "authtoken_token" ("key" varchar(40) NOT NULL PRIMARY KEY, "created" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "catalog_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(40) NOT NULL UNIQUE, "sort_order" integer unsigned NOT NULL CHECK ("sort_order" >= 0), "is_active" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "catalog_product" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(80) NOT NULL, "description" varchar(300) NOT NULL, "price" integer unsigned NOT NULL CHECK ("price" >= 0), "image" varchar(100) NOT NULL, "is_active" bool NOT NULL, "sort_order" integer unsigned NOT NULL CHECK ("sort_order" >= 0), "category_id" bigint NOT NULL REFERENCES "catalog_category" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_product_name_in_category" UNIQUE ("category_id", "name"));
CREATE TABLE IF NOT EXISTS "tables_table" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "number" integer unsigned NOT NULL UNIQUE CHECK ("number" >= 0), "status" varchar(10) NOT NULL, "public_token" varchar(32) NOT NULL UNIQUE, "created_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "tables_tablesession" ("id" char(32) NOT NULL PRIMARY KEY, "entered_at" datetime NOT NULL, "exited_at" datetime NULL, "table_id" bigint NOT NULL REFERENCES "tables_table" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "orders_orderitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "product_name" varchar(80) NOT NULL, "unit_price" integer unsigned NOT NULL CHECK ("unit_price" >= 0), "quantity" smallint unsigned NOT NULL CHECK ("quantity" >= 0), "note" varchar(120) NOT NULL, "order_id" char(32) NOT NULL REFERENCES "orders_order" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" bigint NULL REFERENCES "catalog_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "orders_order" ("id" char(32) NOT NULL PRIMARY KEY, "number" integer unsigned NOT NULL UNIQUE CHECK ("number" >= 0), "source" varchar(10) NOT NULL, "status" varchar(10) NOT NULL, "payment_status" varchar(10) NOT NULL, "payment_method" varchar(15) NULL, "customer_note" varchar(200) NOT NULL, "customer_key" varchar(40) NOT NULL, "total" bigint unsigned NOT NULL CHECK ("total" >= 0), "version" integer unsigned NOT NULL CHECK ("version" >= 0), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "paid_at" datetime NULL, "bar_printed_at" datetime NULL, "session_id" char(32) NOT NULL REFERENCES "tables_tablesession" ("id") DEFERRABLE INITIALLY DEFERRED, "table_id" bigint NOT NULL REFERENCES "tables_table" ("id") DEFERRABLE INITIALLY DEFERRED, "idempotency_key" varchar(64) NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "orders_payment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "method" varchar(15) NOT NULL, "amount" bigint unsigned NOT NULL CHECK ("amount" >= 0), "created_at" datetime NOT NULL, "created_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "order_id" char(32) NOT NULL REFERENCES "orders_order" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "inventory_inventoryitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(60) NOT NULL UNIQUE, "unit" varchar(6) NOT NULL, "current_stock" decimal NOT NULL, "min_stock" decimal NOT NULL, "unit_cost" decimal NOT NULL, "description" varchar(300) NOT NULL, CONSTRAINT "stock_non_negative" CHECK ("current_stock" >= '0'));
CREATE TABLE IF NOT EXISTS "inventory_recipe" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "product_id" bigint NOT NULL UNIQUE REFERENCES "catalog_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "inventory_recipeitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" decimal NOT NULL, "inventory_item_id" bigint NOT NULL REFERENCES "inventory_inventoryitem" ("id") DEFERRABLE INITIALLY DEFERRED, "recipe_id" bigint NOT NULL REFERENCES "inventory_recipe" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_recipe_item" UNIQUE ("recipe_id", "inventory_item_id"));
CREATE TABLE IF NOT EXISTS "core_counter" ("name" varchar(40) NOT NULL PRIMARY KEY, "value" bigint unsigned NOT NULL CHECK ("value" >= 0));
CREATE TABLE IF NOT EXISTS "core_welcomemessage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(120) NOT NULL, "message" text NOT NULL, "enabled" bool NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "core_cafesettings" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL, "address" text NOT NULL, "phone" varchar(40) NOT NULL, "receipt_note" text NOT NULL, "auto_print" bool NOT NULL, "low_stock_alert" bool NOT NULL, "updated_at" datetime NOT NULL, "opening_bank" bigint unsigned NOT NULL CHECK ("opening_bank" >= 0), "opening_cash" bigint unsigned NOT NULL CHECK ("opening_cash" >= 0));
CREATE TABLE IF NOT EXISTS "core_expense" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(120) NOT NULL, "amount" bigint unsigned NOT NULL CHECK ("amount" >= 0), "category" varchar(20) NOT NULL, "date" datetime NOT NULL, "note" text NOT NULL, "account" varchar(5) NOT NULL);
CREATE TABLE IF NOT EXISTS "core_journalline" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "account" varchar(10) NOT NULL, "side" varchar(6) NOT NULL, "amount" bigint unsigned NOT NULL CHECK ("amount" >= 0), "entry_id" bigint NOT NULL REFERENCES "core_journalentry" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_journal_line" UNIQUE ("entry_id", "account", "side"));
CREATE TABLE IF NOT EXISTS "core_journalentry" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "source_type" varchar(20) NOT NULL, "source_id" varchar(40) NOT NULL, "occurred_at" datetime NOT NULL, "title" varchar(160) NOT NULL, "detail" varchar(240) NOT NULL, "method" varchar(15) NOT NULL, "created_at" datetime NOT NULL, "order_id" char(32) NULL REFERENCES "orders_order" ("id") DEFERRABLE INITIALLY DEFERRED, "kind" varchar(15) NOT NULL, CONSTRAINT "uniq_journal_source" UNIQUE ("kind", "source_type", "source_id"));
CREATE TABLE IF NOT EXISTS "core_cafestatus" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "is_open" bool NOT NULL, "opened_at" datetime NULL, "closed_at" datetime NULL);
CREATE TABLE IF NOT EXISTS "core_securitysettings" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "security_hash" varchar(128) NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "credits_debtor" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(80) NOT NULL UNIQUE, "phone" varchar(40) NOT NULL, "note" varchar(200) NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "credits_creditpayment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "amount" bigint unsigned NOT NULL CHECK ("amount" >= 0), "account" varchar(5) NOT NULL, "note" varchar(200) NOT NULL, "idempotency_key" varchar(64) NULL, "created_at" datetime NOT NULL, "created_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "credit_id" bigint NOT NULL REFERENCES "credits_credit" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_credit_payment_idem" UNIQUE ("idempotency_key", "credit_id"), CONSTRAINT "credit_payment_amount_gt_zero" CHECK ("amount" > 0));
CREATE TABLE IF NOT EXISTS "credits_credit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "amount" bigint unsigned NOT NULL CHECK ("amount" >= 0), "remaining_amount" bigint unsigned NOT NULL CHECK ("remaining_amount" >= 0), "status" varchar(10) NOT NULL, "created_at" datetime NOT NULL, "created_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "order_id" char(32) NOT NULL REFERENCES "orders_order" ("id") DEFERRABLE INITIALLY DEFERRED, "debtor_id" bigint NOT NULL REFERENCES "credits_debtor" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_credit_per_order" UNIQUE ("order_id"), CONSTRAINT "credit_remaining_lte_amount" CHECK ("remaining_amount" <= ("amount")));
CREATE TABLE IF NOT EXISTS "inventory_inventorytransaction" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "kind" varchar(15) NOT NULL, "quantity" decimal NOT NULL, "note" varchar(200) NOT NULL, "created_at" datetime NOT NULL, "item_id" bigint NOT NULL REFERENCES "inventory_inventoryitem" ("id") DEFERRABLE INITIALLY DEFERRED, "order_id" char(32) NULL REFERENCES "orders_order" ("id") DEFERRABLE INITIALLY DEFERRED, "unit_cost" decimal NULL, "reason" varchar(20) NULL, "item_name_snapshot" varchar(60) NOT NULL, "account" varchar(5) NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "waiter_calls_waitercall" ("id" char(32) NOT NULL PRIMARY KEY, "status" varchar(13) NOT NULL, "created_at" datetime NOT NULL, "acknowledged_at" datetime NULL, "completed_at" datetime NULL, "acknowledged_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "session_id" char(32) NULL REFERENCES "tables_tablesession" ("id") DEFERRABLE INITIALLY DEFERRED, "table_id" bigint NOT NULL REFERENCES "tables_table" ("id") DEFERRABLE INITIALLY DEFERRED);
